cat > /tmp/httpserve.mjs << 'EOF'
import http from 'http';
import fs from 'fs';
import path from 'path';

const htmlPath = '/Users/younes/.wolffish/workspace/files/world-cup-on-top-2026-06-23.html';
const content = fs.readFileSync(htmlPath, 'utf-8');

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(content);
});

server.listen(9876, () => {
  console.log('Server running at http://localhost:9876');
  process.stdout.write('READY\n');
});

// Keep alive for 5 minutes
setTimeout(() => { server.close(); process.exit(0); }, 300000);
EOF

