  await page.goto('file:///Users/younes/.wolffish/workspace/files/world-cup-on-top-2026-06-23.html', { waitUntil: 'load', timeout: 60000 });
  writeFileSync('/tmp/pdfgen.log', 'Page loaded\n', { flag: 'a' });

  await page.pdf({ path: '/Users/younes/.wolffish/workspace/files/World Cup On Top.pdf', format: 'A4', printBackground: true, margin: { top: '18mm', bottom: '18mm', left: '18mm', right: '18mm' } });
  writeFileSync('/tmp/pdfgen.log', 'PDF saved\n', { flag: 'a' });

  await browser.close();
  writeFileSync('/tmp/pdfgen.log', 'DONE\n', { flag: 'a' });
